Solution 2 – for loop

def factorial(n):
    if n == 0:
        return 1

    result = 1
    for i in range(1, n + 1):
        result *= i

    return result

Solution 4 – while loop

def factorial(n):
    if n == 0:
        return 1

    result = 1
    i = 1
    while i &lt;= n:
        result *= i
        i += 1

    return result

