Start with a populated dictionary:

def count_coins(coins):
    counts = {"pennies": 0,
              "quarters": 0,
              "dimes": 0,
              "nickels": 0}

    for coin in coins:
        if coin == 1:
            counts["pennies"] += 1
        elif coin == 5:
            counts["nickels"] += 1
        elif coin == 10:
            counts["dimes"] += 1
        elif coin == 25:
            counts["quarters"] += 1

    return counts

